app.post('/health', (req, res) => {
  // Could be overwhelmed with huge payloads
  res.json({ status: 'ok' });
});
```

**Recommendation:**
```javascript
// DO: Set body size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: true }));
```

---

