function escapeSQL(str) {
  if (typeof str !== 'string') return str;
  return str.replace(/[\0\n\r\b\t\\\'\"\x1a]/g, (char) => {
    switch (char) {
      case '\0': return '\\0';
      case '\n': return '\\n';
      case '\r': return '\\r';
      case '\b': return '\\b';
