}

// Scope-based Authorization
function authorizeScope(scopes) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    const allowedScopes = (req.user.scopes || []).split(' ');

    const hasScope = scopes.every(scope => allowedScopes.includes(scope));

    if (!hasScope) {
      return res.status(403).json({
        error: 'Insufficient scopes',
        required: scopes,
        granted: allowedScopes,
