```javascript
// require('dotenv').config() should be called BEFORE any other requires

const fs = require('fs');
const path = require('path');
const dotenv = require('dotenv');

/**
 * Securely loads and validates environment variables
 * This function MUST be called before loading any sensitive modules
 */
function setupEnvironment() {
  // 1. Load environment files with priority order
  const envFiles = [
    '.env.local',       // Highest priority - for local development
    `.env.${process.env.NODE_ENV || 'development'}`, // Environment-specific
    '.env.test',         // Test environment
    '.env',             // Base environment variables
  ];

  let loadedFiles = [];

  for (const filePath of envFiles) {
    const fullPath = path.resolve(__dirname, filePath);

    if (fs.existsSync(fullPath)) {
      const result = dotenv.config({ path: fullPath });
      loadedFiles.push(filePath);
      if (result.error) {
        console.warn(`⚠️  Warning: Could not load ${filePath}`, result.error.message);
      }
    }
  }

  console.log(`✅ Environment files loaded: ${loadedFiles.join(', ')}`);

  if (loadedFiles.length === 0) {
    console.warn('⚠️  No .env files found');
  }

  // 2. Validate required environment variables
  validateRequiredEnvVars();

  // 3. Validate environment configuration
  validateEnvConfig();

  return {
    loadedFiles,
    env: process.env,
  };
}

/**
