function validateRequiredEnvVars() {
  const required = [
    'NODE_ENV',
    'JWT_SECRET',          // Must be present for authentication
    'APP_URL',
  ];

  const missing = [];
  const warningOnly = [];

  for (const envVar of required) {
    if (!process.env[envVar]) {
      if (envVar === 'JWT_SECRET' && process.env.NODE_ENV === 'production') {
