# Security Audit Report for app.js

## Summary
This document provides a thorough security analysis of the `app.js` file, identifying vulnerabilities and providing security recommendations.

## Code Analysis

### Current Implementation
```javascript
// Simple application for agent to work on
const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

---

## 🔴 CRITICAL VULNERABILITIES

### 1. Lack of Input Validation (IDS009)
**Severity:** HIGH
**OWASP Category:** A01:2021 – Broken Access Control

**Issue:** No validation of user inputs from query parameters or headers.

**Vulnerable Code:**
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```
No parameters are currently being used, but if expanded later, input validation would be missing.

**Recommendation:**
```javascript
// Input validation middleware
const { body, param, query, validationResult } = require('express-validator');

// For route parameters
app.get('/users/:id', [
  param('id')
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // ... rest of code
});

// For query parameters
app.get('/search', [
  query('q')
    .trim()
    .isLength({ min: 1, max: 100 })
    .escape()
    .withMessage('Search query must be between 1 and 100 characters'),
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // ... rest of code
});
```

---

### 2. Missing Content Security Policy (CSP) (A05:2021 – Security Misconfiguration)
**Severity:** MEDIUM
**OWASP Category:** A05:2021 – Security Misconfiguration

**Issue:** No Content Security Policy (CSP) headers implemented, which could prevent XSS attacks.

**Recommendation:**
```javascript
// Helmet for setting various security headers
const helmet = require('helmet');
app.use(helmet());

// Additional CSP configuration
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'"],
    imgSrc: ["'self'", "data:", "https:"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    mediaSrc: ["'self'"],
    frameSrc: ["'none'"],
    connectSrc: ["'self'"],
    workerSrc: ["'none'"],
    formAction: ["'self'"],
    baseUri: ["'self'"],
    upgradeInsecureRequests: [],
  }
}));

// Additional security headers
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true
}));

app.use(helmet.xssFilter());
app.use(helmet.noSniff());
app.use(helmet.frameguard({ action: 'deny' }));
```

---

### 3. Missing HTTPS Redirection (A05:2021 – Security Misconfiguration)
**Severity:** MEDIUM
**OWASP Category:** A05:2021 – Security Misconfiguration

**Issue:** No enforcement of HTTPS, allowing man-in-the-middle attacks.

**Recommendation:**
```javascript
// Force HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (!req.secure) {
      return res.redirect(301, `https://${req.headers.host}${req.url}`);
    }
    next();
  });
}
```

---

## 🟡 MEDIUM RISK VULNERABILITIES

### 4. No Rate Limiting (A07:2021 – Identification and Authentication Failures)
**Severity:** MEDIUM
**OWASP Category:** A07:2021 – Identification and Authentication Failures

**Issue:** No rate limiting on endpoints, allowing brute-force attacks.

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false
});

app.use(generalLimiter);

// Stricter limiter for sensitive endpoints
const sensitiveLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 10, // Limit each IP to 10 requests per windowMs
  message: {
    error: 'Too many requests, please wait before trying again.'
  }
});

// Apply to sensitive endpoints in production
// app.post('/login', sensitiveLimiter, loginHandler);
```

---

### 5. Sensitive Data Exposure (A02:2021 – Cryptographic Failures)
**Severity:** MEDIUM
**OWASP Category:** A02:2021 – Cryptographic Failures

**Issue:** Debug/development information returned in responses may expose internal details.

**Recommendation:**
```javascript
// Hide detailed error information in production
if (process.env.NODE_ENV === 'production') {
  app.use((err, req, res, next) => {
    console.error(err.stack); // Still log to server console
    res.status(err.status || 500).json({
      error: 'Internal Server Error',
      message: process.env.NODE_ENV === 'production'
        ? 'Something went wrong on our end'
        : err.message
    });
  });
}

// Be careful with versioning headers
app.disable('x-powered-by'); // Remove Express version header
```

---

### 6. No CORS Configuration (A05:2021 – Security Misconfiguration)
**Severity:** MEDIUM
**OWASP Category:** A05:2021 – Security Misconfiguration

**Issue:** CORS not configured, allowing any origin to access resources.

**Recommendation:**
```javascript
const cors = require('cors');

// Allow all origins in development
const corsOptions = {
  origin: process.env.NODE_ENV === 'production'
    ? ['https://yourdomain.com', 'https://www.yourdomain.com']
    : '*', // Allow all origins in development
  credentials: true,
  optionsSuccessStatus: 204
};

app.use(cors(corsOptions));

// More restrictive CORS per route in production
app.get('/api/public', cors(), (req, res) => {
  res.json({ message: 'This is public data' });
});

app.get('/private', cors(corsOptions), (req, res) => {
  res.json({ message: 'This is private data' });
});
```

---

### 7. Information Disclosure (Server Version Header)
**Severity:** LOW
**OWASP Category:** A05:2021 – Security Misconfiguration

**Issue:** Express reveals version information in headers.

**Recommendation:**
```javascript
// Already included above in Helmet section
app.disable('x-powered-by');
```

---

## 🟢 LOW RISK CONCERNS

### 8. Debug Mode Enabled by Default
**Severity:** LOW
**OWASP Category:** A05:2021 – Security Misconfiguration

**Issue:** Node.js debug mode enabled by default can expose significant information.

**Recommendation:**
```javascript
// Set in .env file or production environment
process.env.NODE_ENV = 'production';

// Also ensure these are set:
process.env.DEBUG = ''; // Disable all debug output
process.env.NODE_TLS_REJECT_UNAUTHORIZED = '1'; // Reject invalid certificates
```

---

### 9. Hardcoded Data Exposure
**Severity:** LOW
**OWASP Category:** A01:2021 – Broken Access Control

**Issue:** User data is hardcoded in the application code.

**Recommendation:**
```javascript
// Use environment variables or database
const users = [
  { id: 1, name: process.env.USER1_NAME, email: process.env.USER1_EMAIL },
  { id: 2, name: process.env.USER2_NAME, email: process.env.USER2_EMAIL },
];

// or load from a database
const { Pool } = require('pg'); // or your ORM
const pool = new Pool({
  user: process.env.DB_USER,
  host: process.env.DB_HOST,
  database: process.env.DB_NAME,
  password: process.env.DB_PASSWORD,
  port: process.env.DB_PORT,
});

// Secure environment variables
require('dotenv').config();
```

---

### 10. Error Information Exposure
**Severity:** LOW
**OWASP Category:** A05:2021 – Security Misconfiguration

**Issue:** Stack traces exposed to clients in development.

**Recommendation:**
```javascript
// Implement proper error handling
app.use((err, req, res, next) => {
  console.error(err.stack);

  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: {
      message: isProduction ? 'An unexpected error occurred' : err.message,
      ...(isProduction ? {} : { stack: err.stack }),
      ...(process.env.NODE_ENV === 'development' && { details: err })
    }
  });
});
```

---

## 🛡️ RECOMMENDED SECURITY ENHANCEMENTS

### Complete Secure Version of app.js

```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { validationResult } = require('express-validator');

const app = express();

// Security middleware (order matters)
app.use(helmet()); // Security headers
app.use(cors({
  origin: process.env.NODE_ENV === 'production'
    ? process.env.ALLOWED_ORIGINS?.split(',') || ['https://yourdomain.com']
    : '*',
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per IP
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// Request logging
const morgan = require('morgan');
app.use(morgan('combined')); // Replace 'combined' with 'tiny' for less verbose output

// Input validation for /users/:id
app.get('/users/:id', [
  param('id')
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer')
    .custom(async (value) => {
      // Could check with database here
      // if (!await UserExists(value)) throw new Error('User not found');
      return true;
    })
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Continue with your route logic
  res.json({
    id: req.params.id,
    name: 'Alice',
    email: 'alice@example.com'
  });
});

// Secure health endpoint
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  });
});

// HTTPS redirect for production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (!req.secure) {
      return res.redirect(301, `https://${req.headers.host}${req.url}`);
    }
    next();
  });
}

// Comprehensive error handling
app.use((err, req, res, next) => {
  console.error('Error:', err.stack);

  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: {
      message: isProduction ? 'Internal server error' : err.message,
      ...(isProduction ? {} : { stack: err.stack })
    }
  });
});

// Production startup
if (process.env.NODE_ENV === 'production') {
  app.listen(3000, '0.0.0.0', () => {
    console.log('Secure server running on port 3000');
  });
} else {
  // Development server
  app.listen(3000, 'localhost', () => {
    console.log('Development server running on port 3000');
  });
}

module.exports = app;
```

