// ✅ SECURE PATTERN 3 - AWS Secrets Manager
const AWS = require('aws-sdk');

const getSecret = async (secretName, region = 'us-east-1') => {
  const client = new AWS.SecretsManager({ region });

  const result = await client.getSecretValue({ SecretId: secretName }).promise();

  if (result.SecretString) {
    return JSON.parse(result.SecretString);
  }

  // Binary secret handling
  const buff = Buffer.from(result.SecretBinary, 'base64');
  return buff.toString('utf8');
};

// Usage
const secrets = await getSecret('production/app-secrets');

// Cache for repeated access
const SECRET_CACHE = new Map();
let CACHE_LOCK = false;

const getCachedSecret = async (secretName) => {
  if (SECRET_CACHE.has(secretName)) {
    return SECRET_CACHE.get(secretName);
  }

  // Acquire lock to prevent thundering herd
  while (CACHE_LOCK) await new Promise(resolve => setTimeout(resolve, 10));
  CACHE_LOCK = true;

  try {
    const secret = await getSecret(secretName);
    SECRET_CACHE.set(secretName, secret);
    return secret;
  } finally {
    CACHE_LOCK = false;
  }
};
