  // Redact sensitive parts
  const dbUrl = process.env.DATABASE_URL
    ?.replace(/:[^:@]+@/, ':***@')
    .replace(/\/\/[^:]+:/, '\/\/***:');
  console.log('DB_URL:', dbUrl);
}
```

