## 🔧 Best Practices for Secret Management

### 1. Principle of Least Privilege
- Only grant minimum required permissions
- Rotate secrets regularly
- Use role-based access control

### 2. Dynamic Credentials
- Generate short-lived credentials
- Rotate tokens frequently (AWS Creds: 15min, API tokens: 1h)
- Use IAM roles over credentials

### 3. Secret Scavenging
```javascript
// Add secret checking to middleware
const SECRET_PATTERNS = /[A-Za-z0-9_-]{40,}/g;
const SECRET_ENV_VARS = [
  'DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
  'API_KEY', 'PRIVATE_KEY', 'SECRET', 'TOKEN', 'PASSWORD', 'PASSWORD'
];

// Called at startup for enhanced security
function checkForSecrets() {
  const secretsToCheck = Object.keys(process.env).filter(key =>
    SECRET_ENV_VARS.some(pattern => key.toLowerCase().includes(pattern.toLowerCase()))
  );

  let foundSecrets = false;
  secretsToCheck.forEach(key => {
    const value = process.env[key];
    if (value && SECRET_PATTERNS.test(value)) {
      console.warn(`⚠️  Potential secret detected in environment variable: ${key}`);
      foundSecrets = true;
    }
  });

  return foundSecrets;
}
```

### 4. Secret Sanctity Checks (Runtime)
```javascript
class SecretSanctuary {
  // Prevent console.log console.error from exposing secrets
  static wrapConsole() {
    const originalConsole = Object.assign({}, console);

    const sanitize = (args) => args.map(arg => {
      if (typeof arg === 'string') {
        return arg.replace(/[^\w+=:@.?\/-]/g, (char) => {
          // Don't hide alphanumeric, +, -, _, =, :, @, ., ?, /
          return '*'.repeat(1);
        });
      }
      if (typeof arg === 'object') {
        return JSON.stringify(arg, (key, value) => {
          // Redact any keys with 'secret' in name
          if (typeof key === 'string' && key.toLowerCase().includes('secret')) {
            return '***REDACTED***';
          }
          return value;
        });
      }
      return arg;
    });

    ['log', 'error', 'warn', 'info'].forEach(method => {
      console[method] = (...args) => {
        const sanitized = sanitize(args);
        originalConsole[method].apply(console, sanitized);
      };
    });
  }
}

// Call once at startup
SecretSanctuary.wrapConsole();
```

