```javascript
// ✅ SECURE: Proper secrets management implementation
const crypto = require('crypto');
const fs = require('fs').promises;
const path = require('path');

// Validate environment before starting
function validateRequiredEnv(key, description = 'Required') {
    if (!process.env[key]) {
        throw new Error(`Missing required environment variable: ${description}`);
    }
}

class SecretManager {
    constructor() {
        this.keys = {
            jwtSecret: 'JWT_SECRET',
            databaseUrl: 'DATABASE_URL',
            awsKeyId: 'AWS_ACCESS_KEY_ID',
            awsSecretKey: 'AWS_SECRET_ACCESS_KEY',
            anthropicKey: 'ANTHROPIC_API_KEY',
            stripeKey: 'STRIPE_SECRET_KEY',
            logfireToken: 'LOGFIRE_TOKEN'
        };
    }

    validate() {
        // Validate JWT secret
        if (process.env.NODE_ENV === 'production') {
            validateRequiredEnv(this.keys.jwtSecret);

            // Check JWT secret strength
            const jwtSecret = process.env[this.keys.jwtSecret];
            if (jwtSecret.length < 32) {
                throw new Error('JWT_SECRET must be at least 32 characters');
            }

            // Check for common pattern
            const isWeak = /^[A-Za-z0-9]{32}$/.test(jwtSecret);
            if (isWeak) {
                console.warn('⚠️  JWT_SECRET uses weak format (consider using random bytes)');
            }
        }

        // Validate database URL if present
        if (process.env[this.keys.databaseUrl]) {
            if (!process.env[this.keys.databaseUrl].includes('postgres://')) {
                throw new Error('DATABASE_URL must be a valid PostgreSQL connection string');
            }
        }
    }

    get(key) {
        const value = process.env[key];
        if (!value) return null;

        const isSecret = ['SECRET', 'KEY', 'TOKEN', 'PASSWORD'].find(secret => key.includes(secret));

        return isSecret ? this.maskSecret(value) : value;
    }

    maskSecret(secret) {
        if (!secret || secret.length < 8) return secret;
        return secret.substring(0, 4) + '•'.repeat(4) + secret.substring(secret.length - 4);
    }

    hasSecret(key) {
        return !!process.env[key];
    }
}

// Initialize secret manager
const secrets = new SecretManager();

try {
    secrets.validate();
    console.log('✅ Environment validation passed');

    // Log what secrets are available (without revealing their values)
    Object.entries(secrets.keys).forEach(([desc, key]) => {
        if (secrets.hasSecret(key)) {
            console.log(`✅ ${desc} configured`);
        }
    });
} catch (error) {
    if (process.env.NODE_ENV === 'production') {
        console.error('❌ Environment validation failed:', error.message);
        process.exit(1);
    } else {
        console.warn(`⚠️  Development mode - skipping strict validation: ${error.message}`);
    }
}

module.exports = { secrets };
```

