```javascript
// config/secrets.js - Centralized secrets management
const crypto = require('crypto');

class SecretsManager {
  constructor() {
    this.jwtSecret = process.env.JWT_SECRET;
    this.databaseUrl = process.env.DATABASE_URL;
    this.awsRegion = process.env.AWS_REGION;
    this.azureKeyVault = process.env.AZURE_KEYVAULT_NAME;
  }

  validate() {
    const required = ['JWT_SECRET'];

    if (process.env.NODE_ENV === 'production') {
      required.push('DATABASE_URL');
    }

    const missing = required.filter(req => !this[req]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Add validation for production
    if (process.env.NODE_ENV === 'production' && this.jwtSecret.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters in production');
    }

    return true;
  }

  getJwtSecret() {
    return this.jwtSecret;
  }

  getDatabaseUrl() {
    return this.databaseUrl;
  }
}

module.exports = new SecretsManager();
