    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }),
  helmet.xssFilter(),
  helmet.noSniff(),
  helmet.hidePoweredBy(),
  {
    setHeaders: (res, path) => {
      res.setHeader('X-Content-Type-Options', 'nosniff');
      res.setHeader('X-Frame-Options', 'DENY');
      res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
      res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
    }
  }
];

app.use(securityHeaders);
```

### Debug Mode Enabled

**Problem:**
```javascript
// ✗ DANGEROUS - Debug mode reveals stack traces to clients
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Recommended Fix:**
```javascript
// ✓ SAFE - Production-aware configuration
const NODE_ENV = process.env.NODE_ENV || 'development';
app.set('env', NODE_ENV);

if (NODE_ENV !== 'production') {
  app.use(morgan('dev'));
} else {
  // Only logs in production
  app.use(morgan('combined'));
}

app.listen(process.env.PORT || 3000, () => {
  logger.info(`Server ${NODE_ENV} mode running on port ${process.env.PORT}`);
});

// Error handling - development shows stack traces, production hides them
app.use((err, req, res, next) => {
  logger.error('Server error:', err);
  res.status(err.status || 500).json({
    error: NODE_ENV === 'production' ? 'Internal server error' : err.message
  });
});
```

### CORS Misconfiguration

**Problem:**
```javascript
// ✗ DANGEROUS - Open CORS policy
app.use(cors());
```

**Recommended Fix:**
```javascript
// ✓ SAFE - Strict CORS configuration
const whitelist = [process.env.ALLOWED_ORIGIN, 'https://trusted-domain.com'];
app.use(cors({
  origin: (origin, callback) => {
    if (!origin) return callback(null, true); // Allow mobile apps
    if (whitelist.indexOf(origin) !== -1 || !origin.includes('localhost')) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Request-ID'],
  maxAge: 86400 // Pre-flight request cache for 24 hours
}));
```

---

## 7. Cross-Site Scripting (XSS) (OWASP #7)

### Insufficient Output Encoding

**Problem:**
```javascript
// ✗ DANGEROUS - XSS vulnerability via user input
app.get('/user', (req, res) => {
  const username = req.query.username;
  res.send(`Welcome, ${username}!`);
});
```

**Recommended Fix:**
```javascript
// ✓ SAFE - Proper HTML escaping
const escapeHtml = require('escape-html');

app.get('/user', (req, res) => {
  const username = escapeHtml(req.query.username);
  res.send(`Welcome, ${username}!`);
});
```

### JSON Formatting Issues

**Problem:**
```javascript
// ✗ DANGEROUS - JSONP vulnerability
app.get('/api/data.jsonp', (req, res) => {
  const { callback } = req.query;
  const data = { message: 'Hello' };
  res.send(`${callback}(${JSON.stringify(data)})`);
});
```

**Recommended Fix:**
```javascript
// ✓ SAFE - Use JSONP only with validation
app.get('/api/data.jsonp', (req, res) => {
  const allowedCallbacks = ['getDataFromClient'];
  const { callback } = req.query;

  // Strict callback name validation
  if (!callback || !allowedCallbacks.includes(callback)) {
    return res.status(400).json({ error: 'Invalid callback parameter' });
  }

  // Validate callback is alphanumeric with underscores
  if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(callback)) {
    return res.status(400).json({ error: 'Invalid callback name' });
  }

  const data = { message: 'Hello' };
  res.set('Content-Type', 'application/javascript');
  res.send(`${callback}(${JSON.stringify(data)})`);
});
```

---

## 8. Insecure Deserialization (OWASP #8)

**Problem:**
```javascript
// ✗ DANGEROUS - Unsafe serialization
const order = req.session.order || {};
if (order.items) {
  // Direct serialization of user input
  order.items.forEach(item => {
    // Process item without validation
  });
}
```

**Recommended Fix:**
```javascript
// ✓ SAFE - Validate and normalize serialized objects
const { validationResult } = require('express-validator');

app.post('/cart/add', express.json(), async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Create a new object from request body
  const cartItem = {
    productId: validateObjectId(req.body.productId),
    quantity: validatePositiveNumber(req.body.quantity),
    price: validatePrice(req.body.price)
  };

  // Sanitize and copy only allowed fields
  const sanitizedItem = Object.keys(cartItem).reduce((acc, key) => {
    acc[key] = cartItem[key];
    return acc;
  }, {});

  // Use library with safe deserialization
  const { deserialize } = require('fast-json-patch');
  const deserialized = deserialize(cartItem);

  // Process securely
  await cart.addUserItem(req.user.id, sanitizedItem);
  res.json({ message: 'Item added successfully' });
});
```

---

## 9. Using Components with Known Vulnerabilities (OWASP #9)

**Problem:**
```javascript
// ✗ DANGEROUS - Using outdated libraries
const crypto = require('crypto');
const bcrypt = require('bcrypt');
// Using version with known CVE
```

**Recommended Fix:**
```javascript
// ✓ SAFE - Dependency management
// 1. Use npm audit
const { execSync } = require('child_process');
try {
  const audit = execSync('npm audit --json');
  const vulnerabilities = JSON.parse(audit).vulnerabilities;

  if (Object.keys(vulnerabilities).length > 0) {
    console.error('Vulnerabilities found:', vulnerabilities);
    // Auto-update vulnerable dependencies
    execSync('npm audit fix --force');
  }

  // Run pre-commit hook to check vulnerabilities
} catch (err) {
  logger.error('Dependency scan failed:', err);
}

// Block using eicar test file for antivirus systems
if (process.env.NODE_ENV === 'production') {
  require('./security/libraries-check')();
}
```

---

## 10. Logging and Monitoring Failures (OWASP #10)

**Problem:**
```javascript
// ✗ DANGEROUS - Insecure logging practices
logger.info('User login successful');
```

**Recommended Fix:**
```javascript
// ✓ SAFE - Structured logging with security events
const winston = require('winston');
const { combine, timestamp, printf, colorize } = winston.format;

const securityLogger = winston.createLogger({
  format: combine(
    timestamp(),
    printf(({ timestamp, level, message, ...meta }) => {
      const metaStr = Object.keys(meta).length ? ` ${JSON.stringify(meta)}` : '';
      return `${timestamp} [${level}]: ${message}${metaStr}`;
    })
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'combined.log' }),
    new winston.transports.File({ filename: 'security.log', level: 'info' })
  ]
});

// Security event logging
securityLogger.info('Authentication event', {
  userId: req.user.id,
  timestamp: new Date().toISOString(),
  event: 'LOGIN_SUCCESS',
  userAgent: req.get('User-Agent'),
  ipAddress: req.ip,
  method: req.method,
  path: req.path
});

// Anomaly detection (example)
securityLogger.on('log', function(logData) {
  if (logData.level === 'error' && logData.meta && logData.meta.event) {
    anomalyDetector.detect(logData.meta);
  }
});
```

---

## Additional Security Best Practices

### Rate Limiting

```javascript
// ✓ SAFE - Rate limiting to prevent brute force attacks
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true,
  legacyHeaders: false,
  skipSuccessfulRequests: true,
  handler: (req, res) => {
    securityLogger.warn('Rate limit exceeded', {
      ip: req.ip,
      path: req.path,
      timestamp: new Date().toISOString()
    });
    res.status(429).json({ error: 'Too many requests' });
  }
});

// Apply rate limiting to auth routes
app.use('/api/auth/login', limiter);
app.use('/api/auth/register', limiter);
app.use('/api/auth/forgot-password', limiter);
```

### CSRF Protection

```javascript
