# Secrets Management Security Review

## Critical Findings ⚠️

### 1. `.env` File Storage Issues

**Problem:**
```javascript
// ❌ DANGEROUS: Secrets stored in .env file
// .env file (SHOULD NOT BE IN GIT)
DB_PASSWORD=super_secret_password
JWT_SECRET=very_secure_random_string
AWS_ACCESS_KEY_ID=REDACTED_AWS_AKID
```

**Security Risks:**
- ✗ `.env` files are often committed to version control (Git)
- ✗ `.env` files may have incorrect permissions (leak sensitive access)
- ✗ Any user with access to the repository can see secrets
- ✗ Shared environments (CI/CD, staging) might use the same credentials
- ✗ Serverless functions might expose .env during debugging
- ✗ No automatic rotation of credentials

**Collision Risk:** Multiple instances on the same host could read the same .env file.

---

## Recommended Solution: Vault-based or EKS Secrets Controller

### Option 1: HashiCorp Vault (Enterprise Standard)

```javascript
// ✅ SECURE: Using HashiCorp Vault
const HashiCorpVault = require('node-vault');

const vault = new HashiCorpVault({
  apiVersion: 'v1',
  endpoint: process.env.VAULT_ADDR || 'https://vault.example.com',
  token: await getVaultTokenFromKMS(), // Never store in .env
});

/**
 * Get secret from Vault with caching
 */
async function getSecret(secretPath) {
  try {
    // Get token from secure source (KMS, auth server, etc.)
    const auth = {
      headers: {
        'X-Vault-Token': await getVaultToken()
      }
    };

    const secret = await vault.read(secretPath, auth);
    return secret.data;
  } catch (error) {
    logger.error('Vault access failed', { error: error.message });
    throw new Error('Secret not available');
  }
}

// Initialize with lifecycle management
async function initializeVault() {
  const secrets = {
    database: await getSecret('secret/data/database'),
    jwt: await getSecret('secret/data/app/jwt'),
    api: await getSecret('secret/data/api/keys')
  };

  // Cache vault tokens
  return secrets;
}
```

**Vault Configuration:**
```bash
# .vaultrc (should be in ~/.aws/secretsmanager or ~/.ssh/)
VAULT_ADDR=https://vault.example.com
VAULT_TOKEN=env://VAULT_TOKEN_FILE # Token read from KMS

# .gitignore - DO NOT COMMIT VULT CREDENTIALS
# .env
# .vaultrc
# secrets/
```

---

### Option 2: AWS Secrets Manager (for AWS environments)

```javascript
// ✅ SECURE: Using AWS Secrets Manager
const AWS = require('aws-sdk');

/**
 * AWS Secrets Manager Integration
 * Never store secrets in .env - fetch them at runtime
 */
const secretsManager = new AWS.SecretsManager({
  apiVersion: '2017-10-17',
  region: process.env.AWS_REGION || 'us-east-1'
});

/**
 * Fetch secrets from AWS Secrets Manager
 * Uses caching to reduce API calls
 */
const secretCache = new Map();
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function getAWSSecret(secretName) {
  // Check cache first
  const cached = secretCache.get(secretName);
  if (cached && (Date.now() - cached.timestamp) < CACHE_TTL) {
    return cached.data;
  }

  // Fetch from AWS
  try {
    const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();
    const secretString = data.SecretString ? JSON.parse(data.SecretString) : JSON.parse(data.SecretBinary).toString();

    // Cache the secret
    secretCache.set(secretName, {
      data: secretString,
      timestamp: Date.now()
    });

    return secretString;
  } catch (error) {
    logger.error('AWS Secrets Manager error', { secretName, error: error.message });
    throw new Error(`Failed to fetch secret: ${secretName}`);
  }
}

// Example usage
async function initializeApp() {
  // Fetch secrets from AWS (never from .env)
  const dbConfig = await getAWSSecret('production/db/config');
  const jwtConfig = await getAWSSecret('production/app/jwt');
  const apiKey = await getAWSSecret('production/api/keys');

  // Use secrets in application
  connectToDatabase(dbConfig);
  generateJWT(jwtConfig);
}

// Lambda/Layer friendly - secrets loaded at runtime
module.exports.handler = async (event) => {
  const secrets = await getDatabaseSecret();
  // ... rest of handler
};
```

