### Option 3: Kubernetes Secrets (for containerized apps)

```javascript
// ✅ SECURE: Kubernetes Secrets with ServiceAccount
const { K8sApiV1 } = require('@kubernetes/client-node');

/**
 * Use Kubernetes secret injection via temporary tokens
 * Certs and secrets are injected via kubectl create secret
 */
const kc = K8sApiV1.default();
const secretsInNamespace = kc.makeApiClient(kc.ApiV1SecretApi);

async function getK8sSecret(secretName, namespace = 'default') {
  // Secrets are automatically injected when using security context
  // This function is for secrets that need to be managed separately
  try {
    const response = await secretsInNamespace.readNamespacedSecret(secretName, namespace);
    const { data } = response.body;

    // Decrypt if encrypted (external KMS)
    const decrypted = await decryptSecretData(data);

    return decrypted;
  } catch (error) {
    logger.error('Kubernetes secret error', { secretName, error: error.message });
    throw new Error(`Failed to fetch secret ${secretName}`);
  }
}

/**
 * ServiceAccount scoped secret access (ideal pattern)
 * Do not use hardcoded secrets - use environment injection
 */
// When using GitHub Actions or ArgoCD, secrets injected automatically:
// K8s secrets are mounted as files in /secrets/
app.use('/db', {
  user: process.env.DB_USER,     // Injected from K8s Secret
  password: process.env.DB_PASSWORD,
  host: process.env.DB_HOST
});
